//Define Publisher Adhesion
var pub_adhesion = document.querySelector("div#IL_INSEARCH");

//Define GumGum Events
win.ggevents = win.ggevents || [];

//Capture GumGum Events
win.ggevents.push({

 //Event Handler for In-Screen Load
    'inscreen.load': function (data) {

        //If Publisher Adhesion Exists; Change Visibility to Hidden
        if(pub_adhesion) pub_adhesion.setAttribute('style', 'visibility: hidden !important;');
        if(GUMGUM && GUMGUM.isad){
            GUMGUM.isad.container.style.zIndex = 2147483645;
            //get height of the IS
            let isH = GUMGUM.isad.container.offsetHeight;
            //write styles that you want to add
            let styleText = `html, body {overflow-x: hidden !important;} .st-adunit-ad.st-reset, .ad-mobile-omni-skybox-plus-top-wrapper {visibility: hidden !important;}`;
            //create, configure and add stylesheet element
            var styleSheet = document.createElement("style");
            styleSheet.innerText = styleText;
            styleSheet.id = 'raiseVideo';
            document.head.appendChild(styleSheet);
        }

    },

    'inscreen.close': function (data) {
        //find and delete stylesheet element
        let styleSheet = document.querySelector('style#raiseVideo');
        if(styleSheet){
            styleSheet.disabled = true;
            styleSheet.parentNode.removeChild(styleSheet);
        }
    }

});
